FUNCTION accept_invitation(p_token uuid)
CREATE OR REPLACE FUNCTION public.accept_invitation(p_token uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  inv public.invitations%ROWTYPE;
BEGIN
  SELECT * INTO inv
  FROM public.invitations
  WHERE token       = p_token
    AND accepted_at IS NULL
    AND expires_at  > NOW()
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'Invitation not found, already used, or expired.');
  END IF;

  IF (SELECT email FROM auth.users WHERE id = auth.uid()) != inv.email THEN
    RETURN jsonb_build_object('error', 'This invitation was sent to a different email address.');
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.org_members
    WHERE org_id = inv.org_id AND user_id = auth.uid()
  ) THEN
    RETURN jsonb_build_object('error', 'You are already a member of this organization.');
  END IF;

  INSERT INTO public.org_members (org_id, user_id, role, invited_at, joined_at)
  VALUES (inv.org_id, auth.uid(), inv.role, inv.created_at, NOW());

  UPDATE public.invitations
  SET accepted_at = NOW()
  WHERE id = inv.id;

  RETURN jsonb_build_object('ok', true, 'org_id', inv.org_id);
END;
$function$

FUNCTION calc_installer_note_difficulty()
CREATE OR REPLACE FUNCTION public.calc_installer_note_difficulty()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  total float := 0;
  cnt int := 0;
begin
  if new.rollups       is not null then total := total + new.rollups;       cnt := cnt + 1; end if;
  if new.back_glass    is not null then total := total + new.back_glass;    cnt := cnt + 1; end if;
  if new.windshield    is not null then total := total + new.windshield;    cnt := cnt + 1; end if;
  if new.sunroof       is not null then total := total + new.sunroof;       cnt := cnt + 1; end if;
  if new.quarter_glass is not null then total := total + new.quarter_glass; cnt := cnt + 1; end if;
  new.overall := case when cnt > 0 then round((total / cnt)::numeric, 2) else null end;
  return new;
end;
$function$

FUNCTION calc_installer_note_ppf_difficulty()
CREATE OR REPLACE FUNCTION public.calc_installer_note_ppf_difficulty()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  total float := 0;
  cnt   int   := 0;
begin
  if new.hood           is not null then total := total + new.hood;           cnt := cnt + 1; end if;
  if new.front_bumper   is not null then total := total + new.front_bumper;   cnt := cnt + 1; end if;
  if new.fender         is not null then total := total + new.fender;         cnt := cnt + 1; end if;
  if new.roof           is not null then total := total + new.roof;           cnt := cnt + 1; end if;
  if new.doors          is not null then total := total + new.doors;          cnt := cnt + 1; end if;
  if new.quarter_panels is not null then total := total + new.quarter_panels; cnt := cnt + 1; end if;
  if new.trunk_lid      is not null then total := total + new.trunk_lid;      cnt := cnt + 1; end if;
  if new.rear_bumper    is not null then total := total + new.rear_bumper;    cnt := cnt + 1; end if;
  new.overall := case when cnt > 0 then round((total / cnt)::numeric, 2) else null end;
  return new;
end;
$function$

FUNCTION generate_group_id()
CREATE OR REPLACE FUNCTION public.generate_group_id()
 RETURNS text
 LANGUAGE plpgsql
AS $function$
DECLARE
  chars TEXT := 'abcdefghijklmnopqrstuvwxyz0123456789';
  result TEXT := 'group_';
  i INT;
BEGIN
  FOR i IN 1..16 LOOP
    result := result || substr(chars, floor(random() * length(chars) + 1)::int, 1);
  END LOOP;
  RETURN result;
END;
$function$

FUNCTION generate_po_number(p_org_id uuid)
CREATE OR REPLACE FUNCTION public.generate_po_number(p_org_id uuid)
 RETURNS text
 LANGUAGE plpgsql
AS $function$
declare
  v_next int;
begin
  perform pg_advisory_xact_lock(hashtext('po_number_' || p_org_id::text));
  select coalesce(max(nullif(regexp_replace(po_number, '[^0-9]', '', 'g'), '')::int), 0) + 1
    into v_next
    from public.purchase_orders
    where org_id = p_org_id;
  return 'PO-' || lpad(v_next::text, 5, '0');
end;
$function$

FUNCTION recalc_installer_profile(p_user_id uuid)
CREATE OR REPLACE FUNCTION public.recalc_installer_profile(p_user_id uuid)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
declare
  v_notes_count int;
  v_avg_rating float;
  v_total_votes int;
begin
  select count(*) into v_notes_count
    from installer_notes where user_id = p_user_id and status = 'approved';

  select coalesce(avg(r.stars), 0), count(*)
    into v_avg_rating, v_total_votes
    from installer_note_ratings r
    join installer_notes n on r.note_id = n.id
    where n.user_id = p_user_id;

  update profiles set
    notes_count      = v_notes_count,
    avg_rating       = round(v_avg_rating::numeric, 2),
    contributor_score = round(
      (v_notes_count * 1.0 + v_avg_rating * 2.0 + v_total_votes * 0.5)::numeric, 2
    )
  where id = p_user_id;
end;
$function$

FUNCTION seed_service_categories(p_org_id uuid, p_category_keys text[])
CREATE OR REPLACE FUNCTION public.seed_service_categories(p_org_id uuid, p_category_keys text[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_key   TEXT;
  v_label TEXT;
  v_icon  TEXT;
  v_inv   TEXT;
  v_sort  INT := 0;
BEGIN
  -- Verify caller is an active member of the target org
  IF NOT EXISTS (
    SELECT 1 FROM public.org_members
    WHERE user_id = auth.uid()
      AND org_id   = p_org_id
      AND is_active = TRUE
  ) THEN
    RAISE EXCEPTION 'seed_service_categories: caller is not a member of this org';
  END IF;

  FOREACH v_key IN ARRAY p_category_keys LOOP
    -- Skip if this key already has a row for this org
    IF EXISTS (
      SELECT 1 FROM public.service_categories
      WHERE org_id = p_org_id AND key = v_key
    ) THEN
      v_sort := v_sort + 1;
      CONTINUE;
    END IF;

    CASE v_key
      WHEN 'auto_tint'        THEN v_label := 'Automotive Window Tint'; v_icon := 'car_crash';         v_inv := 'roll';
      WHEN 'arch_tint'        THEN v_label := 'Architectural Tint';      v_icon := 'apartment';         v_inv := 'roll';
      WHEN 'ppf'              THEN v_label := 'PPF';                     v_icon := 'shield';            v_inv := 'roll';
      WHEN 'coatings'         THEN v_label := 'Ceramic Coatings';        v_icon := 'water_drop';        v_inv := 'kit';
      WHEN 'paint_correction' THEN v_label := 'Paint Correction';        v_icon := 'auto_fix_high';     v_inv := 'none';
      WHEN 'detailing'        THEN v_label := 'Detailing';               v_icon := 'cleaning_services'; v_inv := 'unit';
      WHEN 'pdr'              THEN v_label := 'PDR';                     v_icon := 'car_repair';        v_inv := 'none';
      WHEN 'audio_12v'        THEN v_label := '12V / Audio';             v_icon := 'speaker';           v_inv := 'part';
      WHEN 'accessories'      THEN v_label := 'Accessories';             v_icon := 'storefront';        v_inv := 'unit';
      WHEN 'custom'           THEN v_label := 'Custom Service';          v_icon := 'tune';              v_inv := 'none';
      ELSE                         v_label := v_key;                     v_icon := 'category';          v_inv := 'none';
    END CASE;

    INSERT INTO public.service_categories (org_id, key, label, icon, is_enabled, inventory_type, sort_order)
    VALUES (p_org_id, v_key, v_label, v_icon, TRUE, v_inv, v_sort);

    v_sort := v_sort + 1;
  END LOOP;
END;
$function$

FUNCTION set_invoice_number()
CREATE OR REPLACE FUNCTION public.set_invoice_number()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.invoice_number IS NULL OR NEW.invoice_number = '' THEN
    NEW.invoice_number := public.generate_invoice_number(NEW.org_id);
  END IF;
  RETURN NEW;
END;
$function$

