FUNCTION update_contributor_score_on_note()
CREATE OR REPLACE FUNCTION public.update_contributor_score_on_note()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if TG_OP = 'DELETE' then
    perform recalc_installer_profile(old.user_id);
    return old;
  end if;

  -- On insert or update, recalculate for the note author
  perform recalc_installer_profile(new.user_id);
  return new;
end;
$function$

FUNCTION update_installer_contributor_score()
CREATE OR REPLACE FUNCTION public.update_installer_contributor_score()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  v_user_id uuid;
begin
  select user_id into v_user_id from installer_notes where id = new.note_id;
  perform recalc_installer_profile(v_user_id);
  return new;
end;
$function$

